mapper.select:
SELECT
FROM flow_definition d LEFT JOIN workflow_category c ON c.category_code = d.category AND c.is_deleted = 0 WHERE d.del_flag = '0'
AND d.is_publish = 1 AND d.activity_status = 1
AND d.category = #{query.category}
AND d.is_publish = #{query.isPublish}
AND d.activity_status = #{query.activityStatus}
AND (d.flow_code LIKE CONCAT('%', #{query.keyword}, '%') OR d.flow_name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY d.update_time DESC, d.id DESC

SELECT
FROM flow_instance i INNER JOIN flow_definition d ON d.id = i.definition_id AND d.del_flag = '0' LEFT JOIN workflow_category c ON c.category_code = d.category AND c.is_deleted = 0 LEFT JOIN sys_user u ON CAST(u.id AS CHAR) = i.create_by AND u.is_deleted = 0 LEFT JOIN workflow_instance_metadata m ON m.instance_id = i.id AND m.is_deleted = 0 WHERE i.del_flag = '0'
AND i.create_by = #{initiatorId}
AND i.node_type = 2
AND i.node_type != 2
AND d.flow_code = #{query.flowCode}
AND i.flow_status = #{query.flowStatus}
AND (i.business_id LIKE CONCAT('%', #{query.keyword}, '%') OR d.flow_code LIKE CONCAT('%', #{query.keyword}, '%') OR d.flow_name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY i.update_time DESC, i.id DESC

SELECT DISTINCT t.id AS task_id, t.instance_id, t.definition_id, i.business_id, COALESCE(m.business_code, d.flow_code) AS business_code, COALESCE(m.business_title, i.business_id) AS business_title, d.flow_code, d.flow_name, t.node_code, t.node_name, t.flow_status, t.form_custom, t.form_path, n.any_node_skip AS allowed_reject_node_code, t.create_time, t.update_time FROM flow_task t INNER JOIN flow_instance i ON i.id = t.instance_id AND i.del_flag = '0' INNER JOIN flow_definition d ON d.id = t.definition_id AND d.del_flag = '0' INNER JOIN flow_user fu ON fu.associated = t.id AND fu.del_flag = '0' LEFT JOIN flow_node n ON n.definition_id = t.definition_id AND n.node_code = t.node_code AND n.del_flag = '0' LEFT JOIN workflow_instance_metadata m ON m.instance_id = i.id AND m.is_deleted = 0 WHERE t.del_flag = '0' AND t.node_type = 1 AND fu.type IN ('1', '2', '3') AND fu.processed_by IN
#{permission}
AND d.flow_code = #{query.flowCode}
AND (i.business_id LIKE CONCAT('%', #{query.keyword}, '%') OR d.flow_name LIKE CONCAT('%', #{query.keyword}, '%') OR t.node_name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY t.create_time DESC, t.id DESC

SELECT h.task_id, h.id AS history_id, h.instance_id, h.definition_id, i.business_id, COALESCE(m.business_code, d.flow_code) AS business_code, COALESCE(m.business_title, i.business_id) AS business_title, d.flow_code, d.flow_name, h.node_code, h.node_name, h.flow_status, h.form_custom, h.form_path, h.approver AS approver_id, u.nick_name AS approver_name, h.message, h.ext AS attachment_ref, h.create_time, h.update_time FROM flow_his_task h INNER JOIN flow_instance i ON i.id = h.instance_id AND i.del_flag = '0' INNER JOIN flow_definition d ON d.id = h.definition_id AND d.del_flag = '0' LEFT JOIN sys_user u ON CAST(u.id AS CHAR) = h.approver AND u.is_deleted = 0 LEFT JOIN workflow_instance_metadata m ON m.instance_id = i.id AND m.is_deleted = 0 WHERE h.del_flag = '0' AND h.node_type = 1 AND h.approver = #{approverId}
AND d.flow_code = #{query.flowCode}
AND (i.business_id LIKE CONCAT('%', #{query.keyword}, '%') OR d.flow_name LIKE CONCAT('%', #{query.keyword}, '%') OR h.node_name LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY h.update_time DESC, h.id DESC

SELECT COUNT(1) FROM flow_instance i WHERE i.id = #{instanceId} AND i.del_flag = '0' AND ( i.create_by = #{userId} OR EXISTS ( SELECT 1 FROM flow_task t INNER JOIN flow_user fu ON fu.associated = t.id AND fu.del_flag = '0' WHERE t.instance_id = i.id AND t.del_flag = '0' AND fu.type IN ('1', '2', '3') AND fu.processed_by IN
#{permission}
) OR EXISTS ( SELECT 1 FROM flow_his_task h WHERE h.instance_id = i.id AND h.del_flag = '0' AND h.approver = #{userId} ) OR EXISTS ( SELECT 1 FROM workflow_task_copy cp WHERE cp.instance_id = i.id AND cp.recipient_user_id = CAST(#{userId} AS UNSIGNED) AND cp.is_deleted = 0 ) )

SELECT COUNT(1) FROM flow_instance i WHERE i.business_id = #{businessId} AND i.del_flag = '0' AND ( i.create_by = #{userId} OR EXISTS ( SELECT 1 FROM flow_task t INNER JOIN flow_user fu ON fu.associated = t.id AND fu.del_flag = '0' WHERE t.instance_id = i.id AND t.del_flag = '0' AND fu.type IN ('1', '2', '3') AND fu.processed_by IN
#{permission}
) OR EXISTS ( SELECT 1 FROM flow_his_task h WHERE h.instance_id = i.id AND h.del_flag = '0' AND h.approver = #{userId} ) OR EXISTS ( SELECT 1 FROM workflow_task_copy cp WHERE cp.instance_id = i.id AND cp.recipient_user_id = CAST(#{userId} AS UNSIGNED) AND cp.is_deleted = 0 ) )

SELECT COUNT(1)
FROM flow_instance
WHERE definition_id = #{definitionId}
